422	 * @note 文案没变就不动 LVGL（第 ③ 步文案里有当前点名字，每圈都会进这里）。
423	 */
424	static void demo_banner_set(const char * text)
425	{
426	    lv_obj_t * top;
427	
428	    if (text == NULL) {
429	        text = "";
430	    }
431	
432	    /* 退场还没走完又要露脸：停掉退场、就地复位，别删了再建（会闪一下）。 */
433	    if (s_ban != NULL && s_banner_hiding) {
434	        helm_anim_stop(s_ban, demo_banner_y_exec);
435	        helm_anim_stop(s_ban, demo_banner_opa_exec);
436	        s_banner_hiding = false;
437	        lv_obj_set_style_translate_y(s_ban, 0, 0);
438	        lv_obj_set_style_opa(s_ban, LV_OPA_COVER, 0);
439	    }
440	
441	    if (s_ban != NULL && strcmp(s_ban_txt, text) == 0) {
442	        return;
443	    }
444	
445	    strncpy(s_ban_txt, text, sizeof(s_ban_txt) - 1u);
446	    s_ban_txt[sizeof(s_ban_txt) - 1u] = '\0';
447	
448	    if (s_ban == NULL) {
449	        top = lv_layer_top();
450	        if (top == NULL) {
451	            return;
452	        }
453	
454	        s_ban = lv_obj_create(top);
455	        lv_obj_remove_style_all(s_ban);
456	        lv_obj_set_size(s_ban, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
457	        /* 深色实心牌 + 白字：与全局通知横幅同一套观感（半透 200，底下的地图还看得见在动）。 */
458	        lv_obj_set_style_bg_color(s_ban, lv_color_black(), 0);
459	        lv_obj_set_style_bg_opa(s_ban, 200, 0);
460	        lv_obj_set_style_radius(s_ban, 10, 0);
461	        lv_obj_set_style_pad_hor(s_ban, 16, 0);
462	        lv_obj_set_style_pad_ver(s_ban, 9, 0);
463	        lv_obj_clear_flag(s_ban, LV_OBJ_FLAG_SCROLLABLE);
464	        /* 不吃按键/滑动：横幅只是看的，底下的菜单与地图照常收事件。 */
465	        lv_obj_remove_flag(s_ban, LV_OBJ_FLAG_CLICKABLE);
466	        lv_obj_add_flag(s_ban, LV_OBJ_FLAG_FLOATING);
467	        lv_obj_align(s_ban, LV_ALIGN_CENTER, 0, DEMO_BAN_DY);
468	        s_ban_lab = helm_label(s_ban, helm_font_sys(15, helm_font_title()),
469	            0xFFFFFF, s_ban_txt);
470	        demo_banner_enter();
471	    } else {
472	        lv_label_set_text(s_ban_lab, s_ban_txt);
473	        lv_obj_align(s_ban, LV_ALIGN_CENTER, 0, DEMO_BAN_DY);
474	        lv_obj_move_foreground(s_ban);
475	    }
476	
477	    /* 半透底色会跟着底下的地图一起重画：换个新文案后要请它重画一次。 */
478	    lv_obj_invalidate(s_ban);
479	}
