530	/**
531	 * @brief 第 ③ 步：**切换前**就把下一个点的名字挂出来（用户要求"告诉是什么位置"）。
532	 *
533	 * @details 观众面对的是 2 km 窗口里的一块地图，不点名根本不知道跳到哪了。这里的做法是
534	 *          按**自己的时钟**算"现在该是第几个点、还剩多久换点"：快到切换点时（提前
535	 *          `BICYCLE_DEMO_ANNOUNCE_MS`）就报**下一个**点的名字，横幅一直挂到切换后
536	 *          `BICYCLE_DEMO_BAN_MS`。跳点引擎（`bicycle_gnss_hop_*`）按同一周期推进，
537	 *          两者相差不超过一次定位更新的间隔（~200 ms），提前量足够盖住。
538	 */
539	static void demo_nation_announce(void)
540	{
541	    uint32_t el = lv_tick_elaps(s_step_ms);
542	    uint32_t period = BICYCLE_DEMO_HOP_PERIOD_MS;
543	    uint32_t idx = el / period;
544	    const char * name;
545	    char buf[48];
546	
547	    if (idx >= (uint32_t)DEMO_NATION_N) {
548	        idx = (uint32_t)DEMO_NATION_N - 1u;
549	    } else if (((el % period) + BICYCLE_DEMO_ANNOUNCE_MS) >= period
550	               && idx + 1u < (uint32_t)DEMO_NATION_N) {
551	        idx += 1u;                       /* 快到换点了：先报下一个 */
552	    }
553	
554	    name = k_nation_pts[idx].name;
555	
556	    /* 换一个点打一行日志：这是"跳到哪了"唯一的复查依据。 */
557	    if (strcmp(name, s_hop_last) != 0) {
558	        strncpy(s_hop_last, name, sizeof(s_hop_last) - 1u);
559	        s_hop_last[sizeof(s_hop_last) - 1u] = '\0';
560	        syslog(LOG_INFO, "demo: hop -> %s\n", name);
561	
562	        lv_snprintf(buf, sizeof(buf), "%s · %s", k_steps[STEP_NATION].text, name);
563	        demo_banner_show_for(buf, BICYCLE_DEMO_ANNOUNCE_MS + BICYCLE_DEMO_BAN_MS);
564	    }
565	}
