607	/* ============================ 回放起手 ============================ */
608	
609	/**
610	 * @brief 挑一条用来回放的轨迹：用户指定的那条 → 记录/导入目录里最新的那条。
611	 * @param[out] out 命中的完整路径（失败时空串）。
612	 * @return 找到为 true。
613	 * @note 写死的路径**不能是唯一来源**：App 重导一次、换张卡就没了，
614	 *       演示不该因为一个文件名整个起不来。
615	 */
616	static bool demo_pick_gpx(char * out, size_t n)
617	{
618	    static const char * const dirs[] = {
619	        MYVENDOR_GPX_RECORD_DIR,
620	        MYVENDOR_GPX_IMPORT_DIR,
621	    };
622	    char best[192];
623	    unsigned d;
624	
625	    best[0] = '\0';
626	
627	    if (access(BICYCLE_DEMO_GPX, R_OK) == 0) {
628	        strncpy(best, BICYCLE_DEMO_GPX, sizeof(best) - 1u);
629	    }
630	
631	    for (d = 0; d < sizeof(dirs) / sizeof(dirs[0]) && best[0] == '\0'; d++) {
632	        DIR * dir = opendir(dirs[d]);
633	        struct dirent * e;
634	        time_t best_t = 0;
635	
636	        if (dir == NULL) {
637	            continue;
638	        }
639	
640	        while ((e = readdir(dir)) != NULL) {
641	            struct stat st;
642	            char path[192];
643	            size_t len = strlen(e->d_name);
644	            int m;
645	
646	            if (len < 5u || strcasecmp(e->d_name + len - 4u, ".gpx") != 0) {
647	                continue;
648	            }
649	
650	            m = snprintf(path, sizeof(path), "%s/%s", dirs[d], e->d_name);
651	            if (m < 0 || (size_t)m >= sizeof(path)) {
652	                continue;
653	            }
654	
655	            if (stat(path, &st) != 0 || !S_ISREG(st.st_mode)) {
656	                continue;
657	            }
658	
659	            if (best[0] == '\0' || st.st_mtime > best_t) {
660	                best_t = st.st_mtime;
661	                strncpy(best, path, sizeof(best) - 1u);
662	                best[sizeof(best) - 1u] = '\0';
663	            }
664	        }
665	
666	        closedir(dir);
667	    }
668	
669	    if (best[0] == '\0') {
670	        out[0] = '\0';
671	        return false;
672	    }
673	
674	    strncpy(out, best, n - 1u);
675	    out[n - 1u] = '\0';
676	    return true;
677	}
