700	
701	/**
702	 * @brief ①：开指定 GPX 的跟线导航 + 回放当模拟定位；path 为空则自动挑一条。
703	 * @note 明湖模式要**点名**回放含"明湖"的 GPX，所以把"挑文件"与"起导航"拆开；
704	 *       传 NULL 的路径与旧 `demo_enter_gpx_nav()` 完全一致。
705	 */
706	static bool demo_enter_gpx_nav_file(const char * path)
707	{
708	    map_page_t * page = lvgl_page_map();
709	    char picked[192];
710	
711	    if (page == NULL) {
712	        syslog(LOG_WARNING, "demo: no map page\n");
713	        return false;
714	    }
715	
716	    /* 每一步都从干净状态起：清掉上一轮/用户留下的导航（含到达锁存）。 */
717	    map_page_nav_stop(page);
718	
719	    if (path == NULL || path[0] == '\0') {
720	        if (!demo_pick_gpx(picked, sizeof(picked))) {
721	            syslog(LOG_WARNING, "demo: no gpx to play\n");
722	            return false;
723	        }
724	        path = picked;
725	    }
726	
727	    /* ⚠ 顺序不能反：`map_page_nav_from_gpx()` 开头会 `bicycle_gpx_sim_stop()`
728	     * （它默认"跟线用真实定位"）⇒ 先起回放的话会被它一脚踢掉。反过来先开导航、
729	     * 再起回放，两者才同时在线。 */
730	    if (!map_page_nav_from_gpx(page, path, false)) {
731	        syslog(LOG_WARNING, "demo: gpx nav failed (%s)\n", path);
732	        return false;
733	    }
734	
735	    if (map_page_gnss_sim(page, path, false,
736	            bicycle_config_nav_sim_speed_kph(), 0.0f) != 0) {
737	        syslog(LOG_WARNING, "demo: replay failed (%s)\n", path);
738	        map_page_nav_stop(page);
739	        return false;
740	    }
741	
742	    strncpy(s_gpx, path, sizeof(s_gpx) - 1u);
743	    s_gpx[sizeof(s_gpx) - 1u] = '\0';
744	    syslog(LOG_INFO, "demo: step1 gpx nav %s @%.0f km/h\n", path,
745	        (double)bicycle_config_nav_sim_speed_kph());
746	    return true;
747	}
