755	/**
756	 * @brief 读 GPX 里**第一个轨迹点**（演示规划要一个确定的"从哪儿出发"）。
757	 * @return 取到为 true。
758	 *
759	 * @note 为什么不问 `bicycle_runtime_poll_fix()`（2026-09-29 上板翻车的原因）：
760	 *       回放引擎是"全国跳 → 路线模拟 → GPX 回放"三级优先，**回放不是永远说了算**。
761	 *       实测日志里那一次，规划起点取到的是**上一条路线的终点**（= 上一次规划的目的地），
762	 *       于是"从目的地规划到目的地"→ 21 m 路线 → 一开就报到达。
763	 *       轨迹起点是这条回放文件本身的事实，直接读文件最稳；读不到才退回"当前定位"。
764	 * @note 文件是**一整行**的超长 XML（Fly/小米导出都这样），所以按块读、在块里找首点。
765	 */
766	static bool demo_gpx_first_pt(const char * path, double * lon, double * lat)
767	{
768	    char buf[4096];
769	    FILE * f = fopen(path, "r");
770	    size_t n;
771	    const char * p;
772	    bool ok = false;
773	
774	    if (f == NULL) {
775	        return false;
776	    }
777	
778	    n = fread(buf, 1u, sizeof(buf) - 1u, f);
779	    buf[n] = '\0';
780	    (void)fclose(f);
781	
782	    p = strstr(buf, "<trkpt");
783	    if (p != NULL) {
784	        const char * la = strstr(p, "lat=\"");
785	        const char * lo = strstr(p, "lon=\"");
786	
787	        if (la != NULL && lo != NULL && la < p + 256 && lo < p + 256) {
788	            double vlat = strtod(la + 5, NULL);
789	            double vlon = strtod(lo + 5, NULL);
790	
791	            if (vlat >= -90.0 && vlat <= 90.0 && vlon >= -180.0 && vlon <= 180.0) {
792	                *lat = vlat;
793	                *lon = vlon;
794	                ok = true;
795	            }
796	        }
797	    }
798	
799	    return ok;
800	}
