1016	/** @brief 等距圆柱近似两点距离（米）；只用于终点判定，不参与路线生成。 */
1017	static double demo_dist_m(double lat1, double lon1, double lat2, double lon2)
1018	{
1019	    const double r = 6371000.0;
1020	    const double dlat = (lat2 - lat1) * M_PI / 180.0;
1021	    const double dlon = (lon2 - lon1) * M_PI / 180.0;
1022	    const double mlat = (lat1 + lat2) * 0.5 * M_PI / 180.0;
1023	    const double x = dlon * cos(mlat);
1024	
1025	    return sqrt(x * x + dlat * dlat) * r;
1026	}
