1028	/** @brief 按里程/速度估算路线跑完要多久（毫秒）；只做终点检测的兜底。 */
1029	static uint32_t demo_route_duration_ms(double meters, float kph)
1030	{
1031	    double sec;
1032	
1033	    if (kph < 1.0f) {
1034	        kph = 1.0f;
1035	    }
1036	
1037	    sec = meters / ((double)kph / 3.6);
1038	    if (sec < 1.0) {
1039	        sec = 1.0;
1040	    } else if (sec > 86400.0) {
1041	        sec = 86400.0;
1042	    }
1043	
1044	    return (uint32_t)(sec * 1000.0 + 0.5);
1045	}
