1156	{
1157	    bicycle_gnss_fix_t fix;
1158	    double lat = BICYCLE_DEMO_MINGHU_LAT;
1159	    double lon = BICYCLE_DEMO_MINGHU_LON;
1160	    double coslat;
1161	    double dlon;
1162	    int rc;
1163	
1164	    if (bicycle_runtime_poll_fix(&fix) && fix.valid
1165	        && fix.latitude >= -85.0f && fix.latitude <= 85.0f
