1207	        MYVENDOR_GPX_IMPORT_DIR,
1208	        MYVENDOR_GPX_RECORD_DIR,
1209	    };
1210	    char best[192];
1211	    time_t best_t = 0;
1212	    unsigned d;
1213	
1214	    /* 用户点名的文件优先（存在即用，不参与“最新”比较）。 */
1215	    if (access(BICYCLE_DEMO_GPX, R_OK) == 0) {
1216	        strncpy(out, BICYCLE_DEMO_GPX, n - 1u);
1217	        out[n - 1u] = '\0';
1218	        return true;
1219	    }
1220	
1221	    best[0] = '\0';
1222	
1223	    for (d = 0; d < sizeof(dirs) / sizeof(dirs[0]); d++) {
1224	        DIR * dir = opendir(dirs[d]);
1225	        struct dirent * e;
1226	
1227	        if (dir == NULL) {
1228	            continue;
1229	        }
1230	
1231	        while ((e = readdir(dir)) != NULL) {
1232	            struct stat st;
1233	            char path[192];
1234	            size_t len = strlen(e->d_name);
1235	            int m;
1236	
1237	            if (len < 5u || strcasecmp(e->d_name + len - 4u, ".gpx") != 0) {
1238	                continue;
1239	            }
1240	
1241	            if (strstr(e->d_name, "明湖") == NULL) {
1242	                continue;
1243	            }
1244	
1245	            m = snprintf(path, sizeof(path), "%s/%s", dirs[d], e->d_name);
1246	            if (m < 0 || (size_t)m >= sizeof(path)) {
1247	                continue;
1248	            }
1249	
1250	            if (stat(path, &st) != 0 || !S_ISREG(st.st_mode)) {
1251	                continue;
1252	            }
1253	
1254	            if (best[0] == '\0' || st.st_mtime > best_t) {
1255	                best_t = st.st_mtime;
1256	                strncpy(best, path, sizeof(best) - 1u);
1257	                best[sizeof(best) - 1u] = '\0';
1258	            }
1259	        }
1260	
1261	        closedir(dir);
1262	    }
1263	
1264	    if (best[0] == '\0') {
1265	        out[0] = '\0';
1266	        return false;
1267	    }
1268	
1269	    strncpy(out, best, n - 1u);
1270	    out[n - 1u] = '\0';
1271	    return true;
1272	}
