1274	/** @brief 生成绕明湖中心的 72 点环线（等距圆柱近似；东向按 cos(lat) 修正）。 */
1275	static void demo_minghu_build(void)
1276	{
1277	    const double lat0 = BICYCLE_DEMO_MINGHU_LAT;
1278	    const double lon0 = BICYCLE_DEMO_MINGHU_LON;
1279	    const double dlat = BICYCLE_DEMO_MINGHU_RADIUS_M / 110540.0;
1280	    const double dlon = BICYCLE_DEMO_MINGHU_RADIUS_M
1281	        / (111320.0 * cos(lat0 * M_PI / 180.0));
1282	    unsigned i;
1283	
1284	    for (i = 0; i < (unsigned)DEMO_MINGHU_PTS; i++) {
1285	        const double a = 2.0 * M_PI * (double)i / (double)DEMO_MINGHU_PTS;
1286	
1287	        s_minghu_pts[i].lon = lon0 + dlon * cos(a);
1288	        s_minghu_pts[i].lat = lat0 + dlat * sin(a);
1289	    }
1290	}
