1485	/**
1486	 * @brief linear/minghu：到终点后隔 `BICYCLE_DEMO_LOOP_PAUSE_MS` 重开一轮。
1487	 *
1488	 * @note `bicycle_route_sim_active()` 的语义是"线程还在"，**跑完终点也不会变 false**
1489	 *       （只是把定位钉在最后一点）。所以这里除了看 active，还用两条兜底：
1490	 *       ① 当前定位落在终点 `DEMO_ROUTE_END_M` 内；② 按里程/速度估算的时长已到。
1491	 *       三者任一成立即视为到终点，停 2 秒再从头开一轮。
1492	 */
1493	static void demo_mode_route_tick(void)
1494	{
1495	    bicycle_gnss_fix_t fix;
1496	    uint32_t now;
1497	
1498	    if (!s_mode_route) {
1499	        return;
1500	    }
1501	
1502	    now = lv_tick_get();
1503	
1504	    if (s_mode_route_ended) {
1505	        if (lv_tick_elaps(s_mode_route_end_ms) >= BICYCLE_DEMO_LOOP_PAUSE_MS) {
1506	            int rc = demo_mode_route_start(s_mode);
1507	
1508	            if (rc != BICYCLE_DEMO_OK) {
1509	                /* 起不来就再等一轮，别把 UI 线程卡在重试上。 */
1510	                s_mode_route_end_ms = now;
1511	                syslog(LOG_WARNING, "demo: %s restart failed (%d)\n",
1512	                    k_modes[s_mode].name, rc);
1513	            } else {
1514	                syslog(LOG_INFO, "demo: %s loop restart\n", k_modes[s_mode].name);
1515	            }
1516	        }
1517	        return;
1518	    }
1519	
1520	    if (!bicycle_route_sim_active()) {
1521	        s_mode_route_ended = true;
1522	        s_mode_route_end_ms = now;
1523	        syslog(LOG_INFO, "demo: %s route sim stopped, loop in %u ms\n",
1524	            k_modes[s_mode].name, (unsigned)BICYCLE_DEMO_LOOP_PAUSE_MS);
1525	        return;
1526	    }
1527	
1528	    if (s_mode_route_dur_ms > 0u
1529	        && lv_tick_elaps(s_mode_route_start_ms) > s_mode_route_dur_ms + 5000u) {
1530	        s_mode_route_ended = true;
1531	        s_mode_route_end_ms = now;
1532	        syslog(LOG_INFO, "demo: %s route timeout, loop in %u ms\n",
1533	            k_modes[s_mode].name, (unsigned)BICYCLE_DEMO_LOOP_PAUSE_MS);
1534	        return;
1535	    }
1536	
1537	    if (s_mode_route_check_ms != 0u
1538	        && lv_tick_elaps(s_mode_route_check_ms) < DEMO_ROUTE_CHECK_MS) {
1539	        return;
1540	    }
1541	
1542	    s_mode_route_check_ms = now;
1543	    if (bicycle_runtime_poll_fix(&fix) && fix.valid
1544	        && demo_dist_m((double)fix.latitude, (double)fix.longitude,
1545	            s_mode_route_end_lat, s_mode_route_end_lon) <= DEMO_ROUTE_END_M) {
1546	        s_mode_route_ended = true;
1547	        s_mode_route_end_ms = now;
1548	        syslog(LOG_INFO, "demo: %s arrived, loop in %u ms\n",
1549	            k_modes[s_mode].name, (unsigned)BICYCLE_DEMO_LOOP_PAUSE_MS);
1550	    }
1551	}
