1955	/** @brief 场景名/下标解析；-1 = 不认识。纯数字按表下标，其余大小写不敏感。 */
1956	static int demo_scene_find(const char * name)
1957	{
1958	    unsigned i;
1959	
1960	    if (name == NULL || name[0] == '\0') {
1961	        return -1;
1962	    }
1963	
1964	    if (name[0] >= '0' && name[0] <= '9') {
1965	        char * end = NULL;
1966	        unsigned long v = strtoul(name, &end, 10);
1967	
1968	        if (end == NULL || *end != '\0' || v >= (unsigned long)DEMO_SCENE_COUNT) {
1969	            return -1;
1970	        }
1971	
1972	        return (int)v;
1973	    }
1974	
1975	    for (i = 0; i < (unsigned)DEMO_SCENE_COUNT; i++) {
1976	        if (strcasecmp(name, k_scenes[i].name) == 0) {
1977	            return (int)i;
1978	        }
1979	    }
1980	
1981	    return -1;
1982	}
