2021	int bicycle_demo_scene_run(const char * name)
2022	{
2023	    int idx = demo_scene_find(name);
2024	    int rc;
2025	
2026	    if (idx < 0) {
2027	        syslog(LOG_WARNING, "demo: unknown scene '%s'\n", name != NULL ? name : "");
2028	        return BICYCLE_DEMO_SCENE_ERR_UNKNOWN;
2029	    }
2030	
2031	    /* 与循环演示（全量/新增模式）互斥：先停循环（会恢复它翻过的主题）。 */
2032	    if (s_on || s_mode_active) {
2033	        bicycle_demo_stop();
2034	    }
2035	
2036	    if (s_scene_active) {
2037	        demo_scene_leave();
2038	    }
2039	
2040	    /* 第一次进场景时记住原主题；后续换场景不要覆盖，`demo off` 才恢复。 */
2041	    if (!s_theme_hold) {
2042	        demo_theme_save();
2043	    }
2044	
2045	    s_scene = idx;
2046	    s_scene_active = true;
2047	
2048	    rc = demo_scene_enter(idx);
2049	    if (rc != 0) {
2050	        /* 进入失败：回滚到"不在场景"，并把可能已翻掉的主题还原。 */
2051	        demo_scene_leave();
2052	        demo_theme_restore();
2053	        demo_publish();
2054	        syslog(LOG_WARNING, "demo: scene %s failed (%d)\n", k_scenes[idx].name, rc);
2055	        return BICYCLE_DEMO_SCENE_ERR_ENTER;
2056	    }
2057	
2058	    syslog(LOG_NOTICE, "demo: scene %s\n", k_scenes[idx].name);
2059	    return 0;
2060	}
