2062	int bicycle_demo_scene_step(int dir)
2063	{
2064	    const int n = (int)DEMO_SCENE_COUNT;
2065	    int idx;
2066	
2067	    if (s_scene_active && s_scene >= 0 && s_scene < n) {
2068	        idx = (dir < 0) ? ((s_scene + n - 1) % n) : ((s_scene + 1) % n);
2069	    } else {
2070	        idx = (dir < 0) ? (n - 1) : 0;
2071	    }
2072	
2073	    return bicycle_demo_scene_run(k_scenes[idx].name);
2074	}
