2078	int bicycle_demo_start_mode(bicycle_demo_mode_t mode)
2079	{
2080	    const bicycle_runtime_t * rt;
2081	    bool wait_map = false;
2082	    int rc;
2083	
2084	    if ((unsigned)mode >= (unsigned)BICYCLE_DEMO_MODE_COUNT) {
2085	        return BICYCLE_DEMO_ERR_MODE;
2086	    }
2087	
2088	    /* 全量四步沿用旧入口（它自己会停单场景/新增模式）。 */
2089	    if (mode == BICYCLE_DEMO_MODE_FULL) {
2090	        return bicycle_demo_start();
2091	    }
2092	
2093	    if (lvgl_page_map() == NULL) {
2094	        /* 冷机 3~4 s 敲命令时地图页可能还没建好。random 是展会/拍摄最常用的
2095	         * 冷机入口，先记下模式、等 UI 主循环里地图可用再真正进入；其余模式
2096	         * 仍然直接报"地图没准备好"（它们依赖的导航/回放更重，别悄悄排队）。 */
2097	        if (mode != BICYCLE_DEMO_MODE_RANDOM) {
2098	            return BICYCLE_DEMO_ERR_NO_MAP;
2099	        }
2100	
2101	        wait_map = true;
2102	    }
2103	
2104	    /* 与全量/单场景/上一个模式互斥：先全部收干净（会恢复主题）。 */
2105	    if (s_mode_active) {
2106	        demo_mode_leave();
2107	    }
2108	
2109	    if (s_scene_active) {
2110	        demo_scene_leave();
2111	    }
2112	
2113	    if (s_on) {
2114	        bicycle_demo_stop();
2115	    }
2116	
2117	    /* 停掉演示自己的骑行后再判：正在录的真实骑行不能被顶掉。 */
2118	    rt = bicycle_runtime_get();
2119	    if ((rt != NULL && rt->recording) || bicycle_ride_gpx_active()) {
2120	        return BICYCLE_DEMO_ERR_RIDING;
2121	    }
2122	
2123	    /* 从单场景切过来时 `s_theme_hold` 已经存着进场景之前的主题，别覆盖。 */
2124	    if (!s_theme_hold) {
2125	        demo_theme_save();
2126	    }
2127	
2128	    s_mode = mode;
2129	    s_mode_active = true;
2130	    s_mode_enter_pending = false;
2131	    s_mode_enter_wait_ms = 0;
2132	
2133	    if (wait_map) {
2134	        /* 先把状态槽写成 random，命令侧不用等地图；真正进入由 poll 补上。 */
2135	        s_mode_enter_pending = true;
2136	        s_mode_enter_wait_ms = lv_tick_get();
2137	        if (s_mode_enter_wait_ms == 0u) {
2138	            s_mode_enter_wait_ms = 1u;
2139	        }
2140	
2141	        demo_publish();
2142	        syslog(LOG_INFO, "demo: random waits for map page\n");
2143	        return BICYCLE_DEMO_OK;
2144	    }
2145	
2146	    rc = demo_mode_enter(mode);
2147	    if (rc != BICYCLE_DEMO_OK) {
2148	        /* 进入失败：回到"没有演示"，并把可能已经翻掉的主题还原。 */
2149	        demo_mode_leave();
2150	        syslog(LOG_WARNING, "demo: mode %s failed (%d)\n",
2151	            k_modes[mode].name, rc);
2152	        return rc;
2153	    }
2154	
2155	    syslog(LOG_NOTICE, "demo: mode %s\n", k_modes[mode].name);
2156	    return BICYCLE_DEMO_OK;
2157	}
