2159	int bicycle_demo_start(void)
2160	{
2161	    const bicycle_runtime_t * rt = bicycle_runtime_get();
2162	
2163	    /* 新增循环模式与四步循环互斥：先停掉它（会恢复主题/收骑行）。 */
2164	    if (s_mode_active) {
2165	        bicycle_demo_stop();
2166	    }
2167	
2168	    /* 单场景与四步循环互斥：先从场景退出（它会收掉回放/骑行/页面锁）。 */
2169	    if (s_scene_active) {
2170	        demo_scene_leave();
2171	    }
2172	
2173	    if (s_on) {
2174	        return BICYCLE_DEMO_OK;
2175	    }
2176	
2177	    if (lvgl_page_map() == NULL) {
2178	        return BICYCLE_DEMO_ERR_NO_MAP;
2179	    }
2180	
2181	    /* 真实骑行中不开：演示会改里程/轨迹/主题，用户这一趟就废了。 */
2182	    if ((rt != NULL && rt->recording) || bicycle_ride_gpx_active()) {
2183	        return BICYCLE_DEMO_ERR_RIDING;
2184	    }
2185	
2186	    /* 从单场景切回来时 `s_theme_hold` 已经存着**进场景之前**的主题，别覆盖。 */
2187	    if (!s_theme_hold) {
2188	        demo_theme_save();
2189	    }
2190	    s_cycle = 0;
2191	    s_gpx[0] = '\0';
2192	    s_on = true;
2193	
2194	    demo_goto(STEP_GPX_NAV);
2195	    if (s_gpx[0] == '\0') {
2196	        bicycle_demo_stop();
2197	        return BICYCLE_DEMO_ERR_NAV;
2198	    }
2199	
2200	    /* 开演示的唯一入口在菜单里，而演示要看地图 ⇒ 让菜单让位
2201	     * （与"骑行记录 → 导航"同一个姿势：起完导航再收页）。 */
2202	    if (lvgl_page_current_id() == BICYCLE_PM_ID_MENU) {
2203	        (void)lv_pm_close_page_msg(NULL);
2204	    }
2205	
2206	    syslog(LOG_NOTICE, "demo: start (gpx=%s)\n", s_gpx);
2207	    return BICYCLE_DEMO_OK;
2208	}
