2210	void bicycle_demo_stop(void)
2211	{
2212	    map_page_t * page;
2213	
2214	    if (!s_on && !s_scene_active && !s_mode_active) {
2215	        return;
2216	    }
2217	
2218	    /* 先退新增循环模式（停 hop/route/gpx、收骑行、清页面锁/横幅/主题）。 */
2219	    if (s_mode_active) {
2220	        demo_mode_leave();
2221	
2222	        /* 新模式自己已经做完收尾；没有别的循环在跑就不重复。 */
2223	        if (!s_on && !s_scene_active) {
2224	            return;
2225	        }
2226	    }
2227	
2228	    /* 再退单场景（停 nav/回放/骑行、清页面锁）；四步循环两种模式都兼容。 */
2229	    if (s_scene_active) {
2230	        demo_scene_leave();
2231	    }
2232	
2233	    if (!s_on) {
2234	        /* 只有单场景在跑：收横幅、恢复原主题（场景里可能翻过）。 */
2235	        demo_banner_clear();
2236	        demo_theme_restore();
2237	        demo_publish();
2238	        syslog(LOG_NOTICE, "demo: scene stop\n");
2239	        return;
2240	    }
2241	
2242	    s_on = false;
2243	
2244	    /* 跳点在任何一步都可能还开着（比如刚进第 ③ 步就被关）。 */
2245	    bicycle_gnss_hop_stop();
2246	
2247	    page = lvgl_page_map();
2248	    if (page != NULL) {
2249	        if (s_step <= STEP_PLAN_NAV) {
2250	            /* 演示骑行不落盘：每次演示都留一条 TRK 会把骑行记录灌满。 */
2251	            map_page_end_ride(page);
2252	        }
2253	
2254	        map_page_nav_stop(page);
2255	        (void)map_page_gnss_sim(page, NULL, false, 0.0f, 0.0f);
2256	    } else {
2257	        bicycle_gpx_sim_stop();
2258	        bicycle_route_sim_stop();
2259	    }
2260	
2261	    demo_banner_clear();
2262	    demo_theme_restore();
2263	    demo_publish();
2264	    syslog(LOG_NOTICE, "demo: stop (%u cycle(s) done)\n", (unsigned)s_cycle);
2265	}
