2290	    if (s_mode_active && (unsigned)s_mode < (unsigned)BICYCLE_DEMO_MODE_COUNT) {
2291	        if (s_mode == BICYCLE_DEMO_MODE_RANDOM) {
2292	            if (s_mode_enter_pending || s_mode_random_pending) {
2293	                return "随机跳转 · 准备";
2294	            }
2295	
2296	            lv_snprintf(buf, sizeof(buf), "随机跳转 · %s",
2297	                bicycle_gnss_hop_cur_name());
2298	            return buf;
2299	        }
2300	
2301	        return k_modes[s_mode].desc;
2302	    }
2303	
2304	    if (!s_on) {
2305	        return "自动演示：导航 / 跳点 / 主题";
2306	    }
2307	
2308	    switch (s_step) {
2309	    case STEP_NATION:
2310	        lv_snprintf(buf, sizeof(buf), "%s · %s", k_steps[STEP_NATION].text,
2311	            bicycle_gnss_hop_cur_name());
2312	        return buf;
2313	
2314	    case STEP_GPX_NAV:
