2338	void bicycle_demo_poll(void)
2339	{
2340	    map_page_t * page;
2341	    uint32_t elapsed;
2342	
2343	    /* 单场景：不跑四步循环，只管横幅到点收起 + 心率告警的假传感器保持。 */
2344	    if (s_scene_active) {
2345	        demo_banner_tick();
2346	
2347	        if (s_scene_alert_hr && lv_tick_elaps(s_scene_hr_ms) >= 250u) {
2348	            s_scene_hr_ms = lv_tick_get();
2349	            /* 功率压到 150 W（< HELM_ALERT_PWR_W=250）：这一场只点亮心率行，
2350	             * 否则两行同时告警，看不出是哪个场景。 */
2351	            bicycle_runtime_update_sensors(190, true, 90, true, 150, true);
2352	        }
2353	
2354	        return;
2355	    }
2356	
2357	    /* 新增循环模式：random 报点名；linear/minghu 到终点循环重开。 */
2358	    if (s_mode_active) {
2359	        if (s_mode_enter_pending) {
2360	            /* 冷机 random 早到：地图页可用后再进入；本拍先不跑模式节拍。 */
2361	            demo_mode_enter_tick();
2362	            return;
2363	        }
2364	
2365	        demo_mode_poll();
2366	        return;
2367	    }
2368	
2369	    if (!s_on) {
2370	        return;
2371	    }
2372	
2373	    demo_banner_tick();
2374	
2375	    if (s_step == STEP_NATION) {
2376	        demo_nation_announce();       /* 切换前点名（自己带横幅计时） */
2377	    }
2378	
2379	    /* 第 ③ 步：**规划完毕才开始计时**（用户要求）。规划的 route worker 是异步的，
2380	     * 期间把本步起点一直往后挪 = 计时不走；规划一落地就开始数那 30 秒。
2381	     * 上限 `BICYCLE_DEMO_PLAN_WAIT_MAX_MS`：规划卡住时别把演示挂在这儿。 */
2382	    if (s_step == STEP_PLAN_NAV) {
2383	        page = lvgl_page_map();
2384	        if (page != NULL && map_page_nav_planning(page)
2385	            && lv_tick_elaps(s_step_ms) < BICYCLE_DEMO_PLAN_WAIT_MAX_MS) {
2386	            s_step_ms = lv_tick_get();
2387	        } else if (page != NULL && !s_plan_logged && map_page_nav_active(page)) {
2388	            /* 规划落地：打一行"路线就绪 + 点数"，配 `[nav] paint: seen=1 seg=…/N` 就是
2389	             * "规划线真的画出来了"的判据（用户点名要"规划轨迹要绘制"）。 */
2390	            uint32_t pts = 0;
2391	            uint32_t total_cm = 0;
2392	            uint32_t now_idx = 0;
2393	
2394	            (void)map_page_nav_progress(page, &pts, &total_cm, &now_idx, 0);
2395	            s_plan_logged = true;
2396	            map_page_set_arrow_visible(page, true);
2397	            syslog(LOG_INFO, "demo: step2 route ready pts=%u len=%.2fkm arrow=on\n",
2398	                (unsigned)pts, (double)total_cm / 100000.0);
2399	        }
2400	    }
2401	
2402	    elapsed = lv_tick_elaps(s_step_ms);
2403	    if (elapsed < s_step_len_ms) {
2404	        /* 导航段提前收工：到终点了、规划失败了、被手动停了 —— 都没必要把
2405	         * 剩下的时间空耗掉（但给个下限，免得刚起来那两拍规划还没落地就翻页）。 */
2406	        if ((s_step == STEP_GPX_NAV || s_step == STEP_PLAN_NAV)
2407	            && elapsed >= 5000u) {
2408	            page = lvgl_page_map();
2409	            if (page != NULL && !map_page_nav_active(page)
2410	                && !map_page_nav_planning(page)) {
2411	                syslog(LOG_INFO, "demo: nav step %d ended early at %us\n",
2412	                    (int)s_step, (unsigned)(elapsed / 1000u));
2413	            } else {
2414	                return;
2415	            }
2416	        } else {
2417	            return;
2418	        }
2419	    }
2420	
2421	    if (s_step == STEP_THEME) {
2422	#if BICYCLE_DEMO_LOOP
2423	        s_cycle++;
2424	        syslog(LOG_INFO, "demo: cycle %u done, back to step1\n", (unsigned)s_cycle);
2425	        demo_goto((demo_step_t)k_demo_next[STEP_THEME]);
2426	#else
2427	        syslog(LOG_NOTICE, "demo: cycle done, stop\n");
2428	        bicycle_demo_stop();
2429	#endif
2430	        return;
2431	    }
2432	
2433	    demo_goto((demo_step_t)k_demo_next[s_step]);
2434	}
