188	/**
189	 * @brief 自行车 ui ctl parse nav。
190	 */
191	static bool bicycle_ui_ctl_parse_nav(const char * arg, double * from_lon,
192	    double * from_lat, double * to_lon, double * to_lat)
193	{
194	    char buf[MYVENDOR_BICYCLE_CTL_ARG_MAX];
195	    char * tokens[4];
196	    char * save = NULL;
197	    char * p;
198	    int count = 0;
199	
200	    if (!arg || arg[0] == '\0' || !from_lon || !from_lat || !to_lon || !to_lat) {
201	        return false;
202	    }
203	
204	    strncpy(buf, arg, sizeof(buf) - 1);
205	    buf[sizeof(buf) - 1] = '\0';
206	
207	    for (p = strtok_r(buf, ",", &save); p != NULL && count < 4;
208	         p = strtok_r(NULL, ",", &save)) {
209	        tokens[count++] = p;
210	    }
211	
212	    if (count == 2) {
213	        bicycle_gnss_fix_t fix;
214	
215	        if (!bicycle_runtime_poll_fix(&fix) || !fix.valid) {
216	            VMAP_NAV_WARN("ui: no GNSS fix for nav start");
217	            lv_pm_bottom_show("未定位，无法开始导航", 0);
218	            return false;
219	        }
220	        *from_lon = fix.longitude;
221	        *from_lat = fix.latitude;
222	        *to_lon = atof(tokens[0]);
223	        *to_lat = atof(tokens[1]);
224	        return true;
225	    }
226	
227	    if (count == 4) {
228	        *from_lon = atof(tokens[0]);
229	        *from_lat = atof(tokens[1]);
230	        *to_lon = atof(tokens[2]);
231	        *to_lat = atof(tokens[3]);
232	        return true;
233	    }
234	
235	    return false;
236	}
