571	/**
572	 * @brief 演示模式开关 / 单场景切换 / 循环演示模式（`bicycle_nsh demo` / 菜单）。
573	 * @param arg "on"|"off"|"toggle"（空 = 开）；"run:<场景名>"|"next"|"prev" 单场景；
574	 *            "mode:<模式名>"|"start:<模式名>" 循环演示（random/linear/minghu/full）。
575	 */
576	static void bicycle_ui_ctl_handle_demo(const char * arg)
577	{
578	    char msg[64];
579	    int rc;
580	
581	    /* 循环演示模式：mode:<名>/start:<名>（NSH `demo start|mode|on <name>`）。
582	     * 名字表在 bicycle_demo.h，未知名字提示后直接返回，别落到末尾的通用 toast。 */
583	    if (arg != NULL && (strncmp(arg, "mode:", 5) == 0 ||
584	                        strncmp(arg, "start:", 6) == 0)) {
585	        const char * name = strchr(arg, ':') + 1;
586	        int mode = bicycle_demo_mode_from_name(name);
587	
588	        if (mode < 0) {
589	            lv_pm_bottom_show("未知演示模式", 0);
590	            return;
591	        }
592	
593	        rc = bicycle_demo_start_mode((bicycle_demo_mode_t)mode);
594	        if (rc != BICYCLE_DEMO_OK) {
595	            lv_pm_bottom_show("演示模式启动失败", 0);
596	            return;
597	        }
598	
599	        snprintf(msg, sizeof(msg), "演示：%s", bicycle_demo_status());
600	        lv_pm_bottom_show(msg, 0);
601	        return;
602	    }
603	
604	    /* 单场景：run:<name> 由 demo 表查找；未知名字要提示，不能静默。 */
605	    if (arg != NULL && strncmp(arg, "run:", 4) == 0) {
606	        if (arg[4] == '\0') {
607	            lv_pm_bottom_show("未知演示场景", 0);
608	            return;
609	        }
610	
611	        rc = bicycle_demo_scene_run(arg + 4);
612	        if (rc == 0) {
613	            bicycle_ui_ctl_demo_scene_toast();
614	        } else if (rc == BICYCLE_DEMO_SCENE_ERR_UNKNOWN) {
615	            lv_pm_bottom_show("未知演示场景", 0);
616	        } else {
617	            lv_pm_bottom_show("演示场景启动失败", 0);
618	        }
619	        return;
620	    }
621	
622	    if (arg != NULL && (strcmp(arg, "next") == 0 || strcmp(arg, "prev") == 0)) {
623	        rc = bicycle_demo_scene_step(strcmp(arg, "next") == 0 ? 1 : -1);
624	        if (rc == 0) {
625	            bicycle_ui_ctl_demo_scene_toast();
626	        } else {
627	            lv_pm_bottom_show("演示场景启动失败", 0);
628	        }
629	        return;
630	    }
631	
632	    if (arg != NULL && strcmp(arg, "off") == 0) {
633	        bicycle_demo_stop();
634	        lv_pm_bottom_show("演示模式已停止", 0);
635	        return;
636	    }
637	
638	    if (arg != NULL && strcmp(arg, "toggle") == 0) {
639	        bicycle_demo_toggle();
640	    } else if (!bicycle_demo_active()) {
641	        rc = bicycle_demo_start();
642	
643	        if (rc != BICYCLE_DEMO_OK) {
644	            lv_pm_bottom_show(bicycle_demo_error_text(rc), 0);
645	            return;
646	        }
647	    }
648	
649	    snprintf(msg, sizeof(msg), "演示：%s", bicycle_demo_status());
650	    lv_pm_bottom_show(msg, 0);
651	}
